   self.map.raw_entry_mut().from_hash(hash, is_match: |item: &Hashed<K>| -> bool {
       let index: usize = unsafe { item.key.as_usize() };
       let stored_value: <M as Indexable>::Value = unsafe { self.values.value_unchecked_at(index) };
